causal_campaign.static_plugin_source:
"""Controlled structural/public-surface faults for survivors with no runtime call."""

from __future__ import annotations

import pytest


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_call(item):
    nodeid = item.nodeid
    module = item.module
    mp = pytest.MonkeyPatch()
    restore_bases = None

    if "TestVerificationConfidence::test_string_values" in nodeid or "TestPackageSource::test_string_values" in nodeid:
        member = item.funcargs["member"]
        mp.setattr(type(member), "__str__", lambda self: "WP11_BROKEN_ENUM")
    elif "test_pi_and_letta_not_in_command_config" in nodeid:
        module.AGENT_COMMAND_CONFIG["pi"] = {"fault": True}
    elif "TestCommandClassificationInvariant::test_no_overlap_between_sets" in nodeid:
        mp.setattr(module, "PROMPT_DRIVEN_COMMANDS", module.CLI_DRIVEN_COMMANDS)
    elif "test_template_no_lane_in_frontmatter" in nodeid:
        mp.setattr(module, "_has_lane_in_frontmatter", lambda text: ["WP11 injected lane"])
    elif "test_template_no_lane_in_activity_log" in nodeid:
        mp.setattr(module, "_has_lane_in_activity_log", lambda text: ["WP11 injected lane"])
    elif "TestRouterRegistration" in nodeid:
        from specify_cli.dashboard.handlers.glossary import GlossaryHandler
        from specify_cli.dashboard.handlers.lint import LintTileHandler
        from specify_cli.dashboard.handlers.router import DashboardRouter

        restore_bases = DashboardRouter.__bases__
        if "glossary" in nodeid:
            DashboardRouter.__bases__ = tuple(base for base in restore_bases if base is not GlossaryHandler)
        else:
            DashboardRouter.__bases__ = tuple(base for base in restore_bases if base is not LintTileHandler)

    try:
        yield
    finally:
        if restore_bases is not None:
            from specify_cli.dashboard.handlers.router import DashboardRouter

            DashboardRouter.__bases__ = restore_bases
        module.AGENT_COMMAND_CONFIG.pop("pi", None) if "test_pi_and_letta_not_in_command_config" in nodeid else None
        mp.undo()

